def build_track_exam(track_id, track_title, topic_id, topics):
    topic_names = ", ".join(topic[0] for topic in topics)
    practical = TRACK_EXAM_PRACTICE[track_id]
    exam_prompt = f"""Ты проводишь итоговый экзамен по направлению «{track_title}» для кандидата уровня strong junior.

Экзамен должен проверить темы: {topic_names}.

Правила:
1. Не проводи обучение до экзамена и не задавай диагностических вопросов.
2. До начала молча составь матрицу проверки из 12 разных учебных целей. Не показывай её и не начинай экзамен, пока не убедишься, что вопросы не дублируют друг друга по смыслу.
3. Дай 12 вопросов по одному: 4 на понимание разных механизмов, 4 на чтение кода/запроса/конфигурации и прогноз результата, 4 на выбор решения в разных реальных сценариях.
4. Каждый следующий вопрос должен проверять новый механизм, навык или тип рассуждения. Не повторяй и не перефразируй уже заданный вопрос. Уточнение допустимо только один раз, если без него невозможно оценить ответ; оно не считается новым вопросом.
5. Не подсказывай до ответа. После ответа кратко зафиксируй, что верно и что нет, но полный разбор отложи до конца.
6. После вопросов дай практическую часть: {practical}
7. Оцени результат по 100-балльной шкале: теория 40, разбор примеров 25, практика 25, ясность объяснения 10.
8. Готовность к собеседованию: 75+ баллов и отсутствие критического пробела в базовых темах. Не завышай оценку.
9. В финале выдай таблицу: сильные стороны, ошибки, темы для повторения, итоговый балл и вердикт «готов / почти готов / пока не готов».
10. После оценки подробно переобъясни только проваленные темы и проведи по ним короткую повторную проверку другим форматом. Первоначальный балл при этом не меняй.

Начни сразу с вопроса №1."""
    statement = (
        f"Итоговый экзамен по направлению «{track_title}». Скопируйте экзаменационный промпт, "
        "пройдите 12 вопросов и практическую часть без подсказок. После результата сохраните балл и список пробелов."
    )
    return {
        "id": f"{topic_id}-exam", "title": f"Итоговый экзамен: {track_title}",
        "label": "ЭКЗАМЕН", "tab_label": "Экзамен", "kind": "exam",
        "description": statement, "statement": statement,
        "deliverable": "Итоговый балл, вердикт готовности и список тем для повторения.",
        "example": "Проходите экзамен в новом чате, не используя конспект во время ответа.",
        "constraints": [], "checks": [], "acceptance": "", "difficulty": "hard",
        "minutes": 120, "steps": [], "case": practical, "artifact": "exam-report.md",
        "exam_prompt": exam_prompt,
    }


def build_mentor_prompt(track_title, track_goal, topic_title, theory, pitfall, artifact):
    return f"""Ты — мой преподаватель по Python/backend. Дай мне полноценный урок по теме «{topic_title}» из направления «{track_title}» до уровня strong junior.

Считай, что я впервые открыл эту тему и ещё не применял её вручную. Не начинай с диагностики, вопросов, задач или просьбы предсказать результат. Сначала полностью научи.

Цель направления: {track_goal}
Обязательное ядро урока: {theory}
Типичная ошибка, которую нужно подробно разобрать: {pitfall}

ЭТАП 1 — ПОЛНАЯ ТЕОРИЯ И КОНСПЕКТ
Сначала составь внутренний чек-лист покрытия темы, а в ответе покажи его как «Карту урока»: 6–10 конкретных пунктов, которые будут объяснены. Карта обязана включать предпосылки, основной механизм, применение, ограничения и типичную ошибку. Затем последовательно раскрой каждый пункт карты; в конце проверь, что ни один пункт не остался без объяснения.

Это должен быть связный учебный материал обычным языком, а не россыпь тезисов и не пересказ документации. Обязательно раскрой:
— необходимые предварительные понятия, но только те, без которых тема непонятна;
— точную ментальную модель и пошагово то, что происходит внутри;
— новые термины при первом появлении: простое определение, затем точное;
— синтаксис, команды или структуру запроса, если они относятся к теме;
— минимум три разобранных примера: базовый, реалистичный backend-сценарий и контрпример с ошибкой;
— результат каждого примера и причинно-следственное объяснение, почему получился именно он;
— граничные случаи, ограничения и типичные ошибки;
— отличие от похожих инструментов, критерии выбора и ситуации, когда этот инструмент применять не стоит;
— производительность, сложность, безопасность или стоимость операции там, где это имеет смысл;
— что по этой теме обязан уметь strong junior и что уже относится к более редким деталям.

Раздели теорию на логичные главы. В начале главы коротко скажи, на какой вопрос она отвечает. После каждой главы добавляй блок «В конспект» из 3–6 полных предложений, но не задавай мне вопросов. Не пропускай промежуточные шаги и не используй ещё не объяснённые термины. Код, SQL, HTTP, shell-команды и конфигурацию объясняй построчно; примеры должны быть внутренне согласованы и по возможности запускаемы. Не выдумывай поведение инструментов: если деталь зависит от версии или контекста, явно укажи это. Редкие детали помечай как необязательные.

КОНТРОЛЬ КАЧЕСТВА
Перед отправкой молча проверь урок по чек-листу:
— каждый термин определён до использования;
— карта урока полностью покрыта и главы не противоречат друг другу;
— примеры действительно демонстрируют заявленное поведение, а объяснение соответствует их результату;
— факты о реализации не выданы за требования языка или протокола;
— версия инструмента указана там, где от неё зависит поведение;
— нет важного правила без примера и нет примера без объяснения причины;
— материал достаточен, чтобы самостоятельно выполнить теоретическое и практическое задание темы.
Если тема слишком велика для одного ответа, не сжимай и не обрывай важные части: закончи текущую главу, перечисли оставшиеся пункты карты и предложи продолжить теорию. К проверке знаний переходи только после полного покрытия карты.

После теории дай: цельный пример; таблицу «задача → подход → почему → частая ошибка»; раздел «Проверь себя после урока» с тремя утверждениями, которые ученик должен уметь объяснить без конспекта. Затем свернись с картой урока и добавь пропущенное, если оно есть. Только после этого остановись и спроси: «Готов перейти к короткой проверке знаний?» Не начинай проверку, пока я явно не отвечу, что готов.

ЭТАП 2 — ПРОВЕРКА ЗНАНИЙ
После моего согласия проведи только 3 коротких проверки по одной:
1) объяснение основного механизма своими словами;
2) прогноз результата или поиск ошибки в очень коротком примере;
3) одна маленькая практическая задача на применение темы. Она должна проверять тему урока, а не посторонние алгоритмы.

Не повторяй и не перефразируй уже заданный вопрос. Не проверяй один факт несколькими вопросами. Не спрашивай то, чего не было в уроке. Начинай с базового и постепенно усложняй. После ответа дай короткую обратную связь в 1–3 предложениях. Если ответ неоднозначен, разрешено одно уточнение именно к нему; затем переходи к следующей цели матрицы.

ЭТАП 3 — ПОВТОРНОЕ ОБУЧЕНИЕ
После трёх проверок кратко перечисли: что понято, конкретный пробел и что повторить. Если ошибки есть, заново объясни только эти места другими словами и с новым примером. Затем задай максимум один контрольный вопрос по главному пробелу. Если ошибок нет, не придумывай дополнительную теорию или практику.

В конце дай честный результат: «тема усвоена» или «тему нужно повторить», перечисли причины и сформируй итоговый конспект. Не решай за меня практическое задание из приложения и не добавляй домашнюю работу.

Начни сразу с первой главы теории."""


def build_curriculum():
    tracks = []
    for track_index, (track_id, title, icon, color, goal, topics) in enumerate(RAW_TRACKS, 1):
        topics = topics + EXTRA_TOPICS[track_id]
        built_topics = []
        for topic_index, (topic_title, theory, pitfall) in enumerate(topics, 1):
            topic_id = f"{track_id}-{topic_index:02d}"
            tasks = build_unique_tasks(
                track_id, topic_id, topic_title, theory, pitfall,
                ARTIFACTS[track_id], topic_index,
            )
            built_topics.append({
                "id": topic_id,
                "number": topic_index,
                "title": topic_title,
                "theory": theory,
                "pitfall": pitfall,
                "mastery": f"Ты можешь своими словами объяснить «{topic_title}» и, если тема практическая, решить относящуюся к ней задачу без подсказки.",
                "mentor_prompt": build_mentor_prompt(title, goal, topic_title, theory, pitfall, ARTIFACTS[track_id]),
                "practice_links": topic_practice_links(track_id, topic_index),
                "tasks": tasks,
            })
        built_topics[-1]["exam"] = build_track_exam(track_id, title, built_topics[-1]["id"], topics)
        built_topics[-1]["practice_links"].extend(post_exam_links(track_id))
        tracks.append({
            "id": track_id,
            "number": track_index,
            "title": title,
            "icon": icon,
            "color": color,
            "goal": goal,
            "topics": built_topics,
        })
    return tracks


CURRICULUM = build_curriculum()


def all_task_ids():
    return [task["id"] for track in CURRICULUM for topic in track["topics"] for task in topic["tasks"]]


def all_topic_ids():
    return [topic["id"] for track in CURRICULUM for topic in track["topics"]]
